import{_ as r,C as a,c as s,o,aa as n,G as t}from"./chunks/framework.ByRpVre_.js";const C=JSON.parse('{"title":"设置宝箱","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"ExcellentCrates","link":"/wiki/ExcellentCrates"},{"title":"crates","link":""},{"title":"设置宝箱","link":"/wiki/ExcellentCrates/crates/setup-crates"}]},"headers":[],"relativePath":"wiki/ExcellentCrates/crates/setup-crates.md","filePath":"wiki/ExcellentCrates/crates/setup-crates.md"}'),c={name:"wiki/ExcellentCrates/crates/setup-crates.md"};function p(d,e,h,u,_,f){const l=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return o(),s("div",null,[e[0]||(e[0]=n('<h1 id="设置宝箱" tabindex="-1">设置宝箱 <a class="header-anchor" href="#设置宝箱" aria-label="Permalink to &quot;设置宝箱&quot;">​</a></h1><p>在 ExcellentCrates 中创建、编辑与移除宝箱非常简单！</p><p>宝箱配置位于 <strong>/plugins/ExcellentCrates/crates/</strong> 下。</p><p>你可以通过<a href="./../editor-gui">编辑器</a>设置宝箱。</p><h2 id="创建宝箱" tabindex="-1">创建宝箱 <a class="header-anchor" href="#创建宝箱" aria-label="Permalink to &quot;创建宝箱&quot;">​</a></h2><ol><li>打开编辑器 -&gt; <strong>宝箱（Crates）</strong>。</li><li>点击**新建（New Crate）**选项。</li><li>在聊天栏中输入不重复的宝箱名称（只包含英文字符、数字与下划线）。</li><li>大功告成！</li></ol><p>在创建宝箱后，就可以着手配置了：</p><ul><li><a href="./appearance">外观</a></li><li><a href="./previews">预览</a></li><li><a href="./openings">开箱</a></li><li><a href="./placement">放置</a></li><li><a href="./open-cooldown">开箱冷却</a></li><li><a href="./open-cost">开箱收费</a></li><li><a href="./open-permission">开箱权限</a></li><li><a href="./key-requirements">钥匙</a></li><li><a href="./../rewards/setup-rewards">奖励</a></li><li><a href="./milestones">累抽奖励</a></li></ul><h2 id="移除宝箱" tabindex="-1">移除宝箱 <a class="header-anchor" href="#移除宝箱" aria-label="Permalink to &quot;移除宝箱&quot;">​</a></h2><ol><li>输入 <code>/crates editor</code> 命令打开编辑器。</li><li>点击**宝箱（Crates）**按钮。</li><li>点击待删除的宝箱。</li><li>点击**删除（Delete Crate）**按钮</li><li>确认操作后即可。</li></ol><div class="warning custom-block"><p class="custom-block-title">警告</p><p>在删除宝箱后，所有宝箱数据（如最后开启者、奖励限制）会从数据库中永久移除！</p></div>',11)),t(l),t(i)])}const k=r(c,[["render",p]]);export{C as __pageData,k as default};
